import type { JSX, ReactNode } from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { wifPlayer, wifPrivate, wifSnapshot } from "@/stories/fixtures/WhoIsFaker";
import { useWhoIsFakerStore } from "@/stores/UseWhoIsFakerStore";
import { FakerTestController } from "./FakerTestController";

// 动效库在 jsdom 里会往 style 上写中间帧，逐字比对结构前把 motion.* 换成普通元素，
// 只丢掉动效专用属性，className/style/ref/aria/data 原样保留（办法同 GameLayout.test.tsx）。
vi.mock("framer-motion", async (importOriginal) => {
  const actual = await importOriginal<Record<string, unknown>>();
  const MOTION_ONLY = new Set([
    "layout",
    "layoutId",
    "layoutDependency",
    "layoutScroll",
    "variants",
    "initial",
    "animate",
    "exit",
    "transition",
    "custom",
    "whileHover",
    "whileTap",
    "whileFocus",
    "whileDrag",
    "whileInView",
    "drag",
    "dragConstraints",
    "dragElastic",
    "dragMomentum",
    "dragPropagation",
    "dragSnapToOrigin",
    "onAnimationStart",
    "onAnimationComplete",
    "onUpdate",
    "onDrag",
    "onDragStart",
    "onDragEnd",
    "onViewportEnter",
    "onViewportLeave",
    "viewport",
    "transformTemplate",
  ]);
  const cache = new Map<string, unknown>();
  const motion = new Proxy({} as Record<string, unknown>, {
    get(_target, tag) {
      if (typeof tag !== "string") return undefined;
      let component = cache.get(tag);
      if (!component) {
        component = ({
          children,
          ...props
        }: { children?: ReactNode } & Record<string, unknown>) => {
          const dom = Object.fromEntries(
            Object.entries(props).filter(([name]) => !MOTION_ONLY.has(name))
          );
          const Tag = tag as keyof JSX.IntrinsicElements;
          return <Tag {...dom}>{children}</Tag>;
        };
        cache.set(tag, component);
      }
      return component;
    },
  });
  return {
    ...actual,
    motion,
    AnimatePresence: ({ children }: { children?: ReactNode }) => children,
  };
});

// Radix 与 React 的 useId 令牌随组件树位置变化，重构加一层壳就会换值；
// 按出现顺序换成稳定占位符，既去掉抖动又保留 id 与 aria-* 的对应关系。
const normalizeIds = (html: string) => {
  const seen = new Map<string, string>();
  return html.replace(/_r_[0-9a-z]+_/g, (token) => {
    let placeholder = seen.get(token);
    if (!placeholder) {
      placeholder = `«id${seen.size}»`;
      seen.set(token, placeholder);
    }
    return placeholder;
  });
};

type SendCommand = ReturnType<typeof useWhoIsFakerStore.getState>["sendCommand"];

const initialState = useWhoIsFakerStore.getState();

const base = wifSnapshot("day1", { testMode: true });

const withBots = (bots: number, snapshot = base) => ({
  ...snapshot,
  players: [
    ...snapshot.players,
    ...["A", "B"]
      .slice(0, bots)
      .map((suffix) =>
        wifPlayer({ id: `bot-${suffix}`, name: `测试人机 ${suffix}` }, { isBot: true })
      ),
  ],
});

const renderController = (
  bots: number,
  privateState = wifPrivate("me", "day1", { debugRole: "undercover" }),
  snapshot = base
) => {
  const sendCommand = vi.fn(async () => {});
  useWhoIsFakerStore.setState({
    snapshot: withBots(bots, snapshot),
    privateState,
    sendCommand: sendCommand as unknown as SendCommand,
  });
  const view = render(<FakerTestController />);
  return {
    sendCommand,
    html: () => normalizeIds(view.container.firstElementChild!.outerHTML),
  };
};

beforeEach(() => {
  vi.clearAllMocks();
});

afterEach(() => {
  useWhoIsFakerStore.setState(initialState);
});

