describe("FakerTestController 人机行", () => {
  it("加减各发一次真实指令，没有人机时减一个禁用", () => {
    const { sendCommand } = renderController(0);
    const remove = screen.getByRole("button", { name: "移除一个测试人机" });
    expect(remove).toBeDisabled();
    fireEvent.click(remove);
    expect(sendCommand).not.toHaveBeenCalled();

    fireEvent.click(screen.getByRole("button", { name: "添加一个测试人机" }));
    expect(sendCommand).toHaveBeenCalledWith("test.addBot", { count: 1 });
  });

  it("已有人机时减一个发移除指令", () => {
    const { sendCommand } = renderController(2);
    fireEvent.click(screen.getByRole("button", { name: "移除一个测试人机" }));
    expect(sendCommand).toHaveBeenCalledWith("test.removeBot", { count: 1 });
  });
});

describe("FakerTestController 各游戏专属分组", () => {
  it("跳转阶段发真实的跳阶段指令", () => {
    const { sendCommand } = renderController(2);
    fireEvent.click(screen.getByRole("button", { name: "夜晚阶段" }));
    expect(sendCommand).toHaveBeenCalledWith("test.jumpToPhase", { phase: "night" });
  });

  it("切到旁观视角发真实的旁观指令", () => {
    const { sendCommand } = renderController(2);
    fireEvent.click(screen.getByRole("button", { name: "旁观视角" }));
    expect(sendCommand).toHaveBeenCalledWith("player.setSpectator", { spectator: true });
  });
});
